test.describe('Delivery date', () => {
  // The calendar is a grid whose accessible name includes the month and year.
  // Each day is a button inside a gridcell; unavailable days are disabled.
  const calendar = (page) => page.getByRole('grid', { name: /calendar|delivery/i })
  const enabledDay = (page) => calendar(page).locator('button:enabled').first()

  test('opens a calendar and moves between days with the keyboard', async ({ page }) => {
    await page.getByRole('button', { name: /delivery date/i }).click()
    await expect(calendar(page)).toBeVisible()

    await enabledDay(page).focus()
    const before = await page.evaluate(() => document.activeElement?.textContent)
    await page.keyboard.press('ArrowRight')
    const after = await page.evaluate(() => document.activeElement?.textContent)
    expect(after).not.toBe(before)
  })

  test('moves between months', async ({ page }) => {
    await page.getByRole('button', { name: /delivery date/i }).click()
    const before = await calendar(page).getAttribute('aria-label')
    await page.getByRole('button', { name: /next month/i }).click()
    await expect(calendar(page)).not.toHaveAttribute('aria-label', before)
  })

  test('choosing an available day shows the chosen delivery date', async ({ page }) => {
    await page.getByRole('button', { name: /delivery date/i }).click()
    const month = (await calendar(page).getAttribute('aria-label')).match(/[A-Za-z]+/)[0]
    const day = (await enabledDay(page).textContent()).trim()
    await enabledDay(page).click()

    await expect(calendar(page)).toBeHidden()
    await expect(page.getByText(new RegExp(`Delivery.*(${month}\\s+${day}\\b|${day}\\s+${month})`, 'i'))).toBeVisible()
  })

  test('unavailable days cannot be chosen', async ({ page }) => {
    await page.getByRole('button', { name: /delivery date/i }).click()
    const unavailable = calendar(page).locator('button:disabled, [aria-disabled="true"]').first()
    await expect(unavailable).toBeVisible()
    const isDisabled = await unavailable.evaluate((el) => el.disabled || el.getAttribute('aria-disabled') === 'true')
    expect(isDisabled).toBe(true)
  })
})

