import { useId, useState } from 'react'
import { PRODUCT_NAMES } from '../data/product.js'

export default function SearchBox() {
  const [query, setQuery] = useState('')
  const [open, setOpen] = useState(false)
  const [active, setActive] = useState(-1)
  const uid = useId()
  const listId = `${uid}-suggestions`

  const matches = query.trim()
    ? PRODUCT_NAMES.filter((n) => n.toLowerCase().includes(query.trim().toLowerCase()))
    : []
  const showList = open && matches.length > 0

  function choose(name) {
    setQuery(name)
    setOpen(false)
    setActive(-1)
  }

  function onKeyDown(e) {
    if (e.key === 'ArrowDown' && showList) {
      e.preventDefault()
      setActive((a) => Math.min(a + 1, matches.length - 1))
    } else if (e.key === 'ArrowUp' && showList) {
      e.preventDefault()
      setActive((a) => Math.max(a - 1, 0))
    } else if (e.key === 'Enter' && showList && active >= 0) {
      e.preventDefault()
      choose(matches[active])
    } else if (e.key === 'Escape' && showList) {
      e.preventDefault()
      setOpen(false)
      setActive(-1)
    }
  }

  return (
    <form role="search" className="search" onSubmit={(e) => e.preventDefault()}>
      <label htmlFor={`${uid}-input`} className="visually-hidden">
        Search products
      </label>
      <input
        id={`${uid}-input`}
        type="search"
        autoComplete="off"
        value={query}
        onChange={(e) => {
          setQuery(e.target.value)
          setOpen(true)
          setActive(-1)
        }}
        onKeyDown={onKeyDown}
        onBlur={() => setOpen(false)}
        aria-autocomplete="list"
        aria-controls={showList ? listId : undefined}
        aria-expanded={showList ? 'true' : 'false'}
        aria-activedescendant={showList && active >= 0 ? `${listId}-${active}` : undefined}
      />
      {showList && (
        <ul id={listId} role="listbox" aria-label="Suggestions" className="suggestions">
          {matches.map((name, i) => (
            <li
              key={name}
              id={`${listId}-${i}`}
              role="option"
              aria-selected={i === active ? 'true' : 'false'}
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => choose(name)}
            >
              {name}
            </li>
          ))}
        </ul>
      )}
    </form>
  )
}
