// Disclosure navigation: one top-level section open at a time.
// Subsections with children drill in and show a Back button.
export default function MainMenu() {
  const [openIndex, setOpenIndex] = useState(null)
  const [drill, setDrill] = useState(null) // { section, label, children }
  const uid = useId()

  function toggle(i) {
    setOpenIndex((cur) => (cur === i ? null : i))
    setDrill(null)
  }

  return (
    <nav aria-label="Main" className="main-menu">
      <ul className="main-menu-list">
        {MENU.map((section, i) => {
          const expanded = openIndex === i
          const panelId = `${uid}-panel-${i}`
          return (
            <li key={section.label}>
              <button
                type="button"
                aria-expanded={expanded ? 'true' : 'false'}
                aria-controls={panelId}
                onClick={() => toggle(i)}
              >
                {section.label}
              </button>
              <div id={panelId} hidden={!expanded} className="menu-panel">
                {expanded && drill && (
                  <>
                    <button type="button" className="menu-back" onClick={() => setDrill(null)}>
                      Back to {section.label}
                    </button>
                    <p className="menu-drill-title">{drill.label}</p>
                    <ul>
