                        </li>
                      ))}
                    </ul>
                  </>
                )}
                {expanded && !drill && (
                  <ul>
                    {section.items.map((item) =>
                      item.children ? (
                        <li key={item.label}>
                          <button type="button" onClick={() => setDrill(item)}>
                            {item.label}
