                        </li>
                      ) : (
                        <li key={item.label}>
                          <a href={item.href}>{item.label}</a>
                        </li>
                      ),
                    )}
                  </ul>
                )}
              </div>
            </li>
          )
        })}
        <li>
          <a href="/sale">Sale</a>
        </li>
      </ul>
    </nav>
  )
}
