import { useEffect, useId, useRef, useState } from 'react'
import { SIZES } from '../data/product.js'

// soldOut: array of booleans per SIZES index.
export default function SizePicker({ size, soldOut, onChange, buttonRef }) {
  const [open, setOpen] = useState(false)
  const [active, setActive] = useState(0)
  const listRef = useRef(null)
  const uid = useId()
  const listId = `${uid}-sizes`

  useEffect(() => {
    if (open) listRef.current?.focus()
  }, [open])

  function close(returnFocus) {
    setOpen(false)
    if (returnFocus) buttonRef.current?.focus()
  }

  function pick(i) {
    if (soldOut[i]) return
    onChange(SIZES[i])
    close(true)
  }

  function openList() {
    const current = size ? SIZES.indexOf(size) : -1
    setActive(current >= 0 ? current : soldOut.findIndex((s) => !s))
    setOpen(true)
  }

  function onKeyDown(e) {
    if (e.key === 'ArrowDown') {
      e.preventDefault()
      setActive((a) => Math.min(a + 1, SIZES.length - 1))
    } else if (e.key === 'ArrowUp') {
      e.preventDefault()
      setActive((a) => Math.max(a - 1, 0))
    } else if (e.key === 'Home') {
      e.preventDefault()
      setActive(0)
    } else if (e.key === 'End') {
      e.preventDefault()
      setActive(SIZES.length - 1)
    } else if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault()
      pick(active)
    } else if (e.key === 'Escape') {
      e.preventDefault()
      close(true)
    }
  }

  return (
    <div className="size-picker">
      <button
        type="button"
        ref={buttonRef}
        className="select-button"
        aria-haspopup="listbox"
        aria-expanded={open ? 'true' : 'false'}
        aria-controls={open ? listId : undefined}
        onClick={() => (open ? close(false) : openList())}
      >
        Size: {size ? `US ${size}` : 'Select a size'}
