      {open && (
        <ul
          id={listId}
          ref={listRef}
          role="listbox"
          aria-label="Size"
          tabIndex={-1}
          aria-activedescendant={`${listId}-${active}`}
          onKeyDown={onKeyDown}
          onBlur={(e) => {
