import { useEffect, useRef } from 'react'
import { createPortal } from 'react-dom'

// Modal dialog: rendered outside the page root, which is hidden from assistive tech while open.
// Focus is trapped inside, Escape closes, and focus returns to the opener.
export default function Dialog({ labelledBy, onClose, children }) {
  const ref = useRef(null)

  useEffect(() => {
    const root = document.getElementById('root')
    const opener = document.activeElement
    root.setAttribute('aria-hidden', 'true')
    root.setAttribute('inert', '')
    const first = ref.current?.querySelector('input, button, [href], select, textarea')
    first?.focus()

    function onKeyDown(e) {
      if (e.key === 'Escape') {
        e.preventDefault()
        onClose()
        return
      }
      if (e.key !== 'Tab') return
      const items = [...ref.current.querySelectorAll('input, button, [href], select, textarea')].filter(
        (el) => !el.disabled,
      )
      if (items.length === 0) return
      const firstEl = items[0]
      const lastEl = items[items.length - 1]
      if (e.shiftKey && document.activeElement === firstEl) {
        e.preventDefault()
        lastEl.focus()
      } else if (!e.shiftKey && document.activeElement === lastEl) {
        e.preventDefault()
        firstEl.focus()
      }
    }

    document.addEventListener('keydown', onKeyDown)
    return () => {
      document.removeEventListener('keydown', onKeyDown)
      root.removeAttribute('aria-hidden')
      root.removeAttribute('inert')
      opener?.focus?.()
    }
  }, [onClose])

  return createPortal(
    <div className="dialog-backdrop">
      <div ref={ref} role="dialog" aria-modal="true" aria-labelledby={labelledBy} className="dialog">
        {children}
      </div>
    </div>,
    document.body,
  )
}
