import { useRef, useState } from 'react'
import { SIZES, STORES, STOCK } from '../data/product.js'

// Grid: stores as rows, sizes as columns. Arrow keys move between cells; unavailable cells are disabled.
export default function StoreAvailability({ pickup, onPick }) {
  const [focus, setFocus] = useState({ r: 0, c: 0 })
  const refs = useRef({})

  function move(r, c) {
    // Step through cells in the arrow direction, skipping unavailable ones.
    setFocus({ r, c })
    refs.current[`${r}-${c}`]?.focus()
  }

  function onKeyDown(e, r, c) {
    const deltas = { ArrowRight: [0, 1], ArrowLeft: [0, -1], ArrowDown: [1, 0], ArrowUp: [-1, 0] }
    const d = deltas[e.key]
    if (!d) return
    e.preventDefault()
    let nr = r
    let nc = c
    for (;;) {
      nr += d[0]
      nc += d[1]
      if (nr < 0 || nr >= STORES.length || nc < 0 || nc >= SIZES.length) return
      if (STOCK[nr][nc]) break
    }
    move(nr, nc)
  }

  return (
    <div className="store-availability">
      <table role="grid" aria-label="Store availability" className="store-grid">
        <thead>
          <tr>
            <td aria-hidden="true" />
            {SIZES.map((s) => (
              <th key={s} scope="col">
                US {s}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {STORES.map((store, r) => (
            <tr key={store}>
              <th scope="row">{store}</th>
              {SIZES.map((s, c) => {
                const available = STOCK[r][c]
                const selected = pickup && pickup.store === r && pickup.size === s
                const tabbable = focus.r === r && focus.c === c
                return (
                  <td key={s} role="gridcell" aria-selected={selected ? 'true' : 'false'}>
                    <button
                      type="button"
                      ref={(el) => (refs.current[`${r}-${c}`] = el)}
                      tabIndex={tabbable ? 0 : -1}
                      disabled={!available}
                      aria-pressed={selected ? 'true' : 'false'}
                      aria-label={`${store}, US ${s}, ${available ? 'in stock' : 'unavailable'}`}
                      onFocus={() => setFocus({ r, c })}
                      onKeyDown={(e) => onKeyDown(e, r, c)}
                      onClick={() => onPick({ store: r, size: s })}
                      className={selected ? 'cell is-selected' : 'cell'}
                    >
                      {available ? 'In stock' : '—'}
                    </button>
                  </td>
                )
              })}
            </tr>
          ))}
        </tbody>
      </table>
      {pickup && (
        <p className="pickup-note">
          Pickup at {STORES[pickup.store]}, US {pickup.size}
        </p>
      )}
    </div>
  )
}
