import { useId, useState } from 'react'

const MAX = 10

export default function Quantity({ value, onChange }) {
  const [text, setText] = useState(String(value))
  const uid = useId()

  function commit(n) {
    const clamped = Math.min(MAX, Math.max(1, n))
    setText(String(clamped))
    onChange(clamped)
  }

  return (
    <div className="field">
      <label htmlFor={`${uid}-qty`}>Quantity</label>
      <div className="quantity">
        <button type="button" aria-label="Decrease quantity" onClick={() => commit(value - 1)}>
          &minus;
        </button>
        <input
          id={`${uid}-qty`}
          type="number"
          min="1"
          max={MAX}
          value={text}
          onChange={(e) => {
            setText(e.target.value)
            const n = parseInt(e.target.value, 10)
            if (n >= 1 && n <= MAX) onChange(n)
          }}
          onBlur={() => commit(parseInt(text, 10) || 1)}
        />
        <button type="button" aria-label="Increase quantity" onClick={() => commit(value + 1)}>
          +
        </button>
      </div>
    </div>
  )
}
