import { useEffect, useId, useRef, useState } from 'react'

const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
const MONTHS = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December',
]

const DAY_MS = 86400000
const key = (d) => `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`
const startOfDay = (d) => new Date(d.getFullYear(), d.getMonth(), d.getDate())
const addDays = (d, n) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n)

// Earliest delivery is two days from today; Sundays are not delivered.
function isAvailable(d, minDate) {
  return d >= minDate && d.getDay() !== 0
}

export default function DeliveryDate({ selected, onSelect }) {
  const uid = useId()
  const today = startOfDay(new Date())
  const minDate = addDays(today, 2)
  const [open, setOpen] = useState(false)
  const [focusDate, setFocusDate] = useState(selected ?? minDate)
  const [view, setView] = useState(() => new Date(focusDate.getFullYear(), focusDate.getMonth(), 1))
  const buttonRef = useRef(null)
  const dayRefs = useRef({})
  const movingFocus = useRef(false)

  // Keep focus on the day cell after keyboard navigation.
  useEffect(() => {
    if (open && movingFocus.current) {
      dayRefs.current[key(focusDate)]?.focus()
      movingFocus.current = false
    }
  }, [open, focusDate])

  function openCalendar() {
    const start = selected ?? focusDate
    setFocusDate(start)
    setView(new Date(start.getFullYear(), start.getMonth(), 1))
    setOpen(true)
    movingFocus.current = true
  }

  function closeCalendar(returnFocus) {
    setOpen(false)
    if (returnFocus) buttonRef.current?.focus()
  }

  function shiftMonth(n) {
    setView((v) => new Date(v.getFullYear(), v.getMonth() + n, 1))
  }

  function pick(d) {
    onSelect(d)
    closeCalendar(true)
  }

  // Move the roving focus by delta days, skipping unavailable days in that direction.
  function moveFocus(delta) {
    let d = focusDate
    for (let i = 0; i < 62; i++) {
      d = addDays(d, delta)
      if (isAvailable(d, minDate)) break
    }
    if (!isAvailable(d, minDate)) return
    setFocusDate(d)
    if (d.getMonth() !== view.getMonth() || d.getFullYear() !== view.getFullYear()) {
      setView(new Date(d.getFullYear(), d.getMonth(), 1))
    }
    movingFocus.current = true
  }

  function onGridKeyDown(e) {
    const map = { ArrowRight: 1, ArrowLeft: -1, ArrowDown: 7, ArrowUp: -7 }
    if (e.key in map) {
      e.preventDefault()
      moveFocus(map[e.key])
    } else if (e.key === 'PageDown' || e.key === 'PageUp') {
      e.preventDefault()
      const d = addDays(focusDate, 0)
      const next = new Date(d.getFullYear(), d.getMonth() + (e.key === 'PageDown' ? 1 : -1), Math.min(d.getDate(), 28))
      if (isAvailable(next, minDate)) {
        setFocusDate(next)
        setView(new Date(next.getFullYear(), next.getMonth(), 1))
        movingFocus.current = true
      }
    } else if (e.key === 'Escape') {
      e.preventDefault()
      closeCalendar(true)
    }
  }

  // Build the weeks of the viewed month.
  const first = new Date(view.getFullYear(), view.getMonth(), 1)
  const daysInMonth = new Date(view.getFullYear(), view.getMonth() + 1, 0).getDate()
  const cells = []
  for (let i = 0; i < first.getDay(); i++) cells.push(null)
  for (let day = 1; day <= daysInMonth; day++) cells.push(new Date(view.getFullYear(), view.getMonth(), day))
  while (cells.length % 7 !== 0) cells.push(null)
  const weeks = []
  for (let i = 0; i < cells.length; i += 7) weeks.push(cells.slice(i, i + 7))

  const focusInView =
    focusDate.getMonth() === view.getMonth() && focusDate.getFullYear() === view.getFullYear()
  const viewLabel = `${MONTHS[view.getMonth()]} ${view.getFullYear()}`

  return (
    <div className="delivery">
      <button
        type="button"
        ref={buttonRef}
        aria-expanded={open ? 'true' : 'false'}
        aria-controls={open ? `${uid}-calendar` : undefined}
        onClick={() => (open ? closeCalendar(false) : openCalendar())}
        className="select-button"
      >
        Delivery date
      </button>
      {selected && (
        <p className="delivery-chosen">
          Delivery: {WEEKDAYS[selected.getDay()]}, {MONTHS[selected.getMonth()]} {selected.getDate()},{' '}
          {selected.getFullYear()}
        </p>
      )}
      {open && (
        <div id={`${uid}-calendar`} className="calendar-panel">
          <div className="calendar-nav">
            <button type="button" onClick={() => shiftMonth(-1)} aria-label="Previous month">
              &larr;
            </button>
            <span aria-hidden="true">{viewLabel}</span>
            <button type="button" onClick={() => shiftMonth(1)} aria-label="Next month">
              &rarr;
            </button>
          </div>
          <table
            role="grid"
            aria-label={`${viewLabel} delivery calendar`}
            className="calendar"
            onKeyDown={onGridKeyDown}
          >
            <thead>
              <tr>
                {WEEKDAYS.map((w) => (
                  <th key={w} scope="col" abbr={w}>
                    {w.slice(0, 2)}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {weeks.map((week, wi) => (
                <tr key={wi}>
                  {week.map((d, di) =>
                    d ? (
                      <td key={di} role="gridcell" aria-selected={selected && key(selected) === key(d) ? 'true' : undefined}>
                        <button
                          type="button"
                          ref={(el) => (dayRefs.current[key(d)] = el)}
                          disabled={!isAvailable(d, minDate)}
                          tabIndex={key(d) === key(focusDate) || (!focusInView && d.getDate() === 1) ? 0 : -1}
                          onFocus={() => setFocusDate(d)}
                          onClick={() => pick(d)}
                          aria-label={`${WEEKDAYS[d.getDay()]}, ${MONTHS[d.getMonth()]} ${d.getDate()}`}
                        >
                          {d.getDate()}
                        </button>
                      </td>
                    ) : (
                      <td key={di} />
                    ),
                  )}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  )
}
