import { useRef, useState } from 'react'
import SearchBox from '../components/SearchBox.jsx'
import MainMenu from '../components/MainMenu.jsx'
import Breadcrumb from '../components/Breadcrumb.jsx'
import PhotoGallery from '../components/PhotoGallery.jsx'
import PriceInfo from '../components/PriceInfo.jsx'
import ColorPicker from '../components/ColorPicker.jsx'
import SizePicker from '../components/SizePicker.jsx'
import SizeGuide from '../components/SizeGuide.jsx'
import StoreAvailability from '../components/StoreAvailability.jsx'
import Quantity from '../components/Quantity.jsx'
import DeliveryDate from '../components/DeliveryDate.jsx'
import ProductTabs from '../components/ProductTabs.jsx'
import Faq from '../components/Faq.jsx'
import Footer from '../components/Footer.jsx'
import { SIZES, STOCK } from '../data/product.js'

const PRODUCT = {
  name: 'Trail Runner 2',
  price: '$180',
  intro: 'A lightweight trail shoe with a grippy outsole and a supportive, breathable upper.',
}

// A size is sold out when no store has it in stock.
const SOLD_OUT = SIZES.map((_, c) => STOCK.every((row) => !row[c]))

export default function ProductPage() {
  const [color, setColor] = useState('Blue')
  const [size, setSize] = useState(null)
  const [pickup, setPickup] = useState(null) // { store, size }
  const [quantity, setQuantity] = useState(1)
  const [delivery, setDelivery] = useState(null)
  const [guideOpen, setGuideOpen] = useState(false)
  const [wishlisted, setWishlisted] = useState(false)
  const [cartCount, setCartCount] = useState(0)
  const [sizeError, setSizeError] = useState('')
  const [status, setStatus] = useState('')

  const sizeButtonRef = useRef(null)
  const guideButtonRef = useRef(null)

  function addToCart() {
    if (!size) {
      setSizeError('Please select a size before adding to cart.')
      setStatus('')
      sizeButtonRef.current?.focus()
      return
    }
    setSizeError('')
    setCartCount((n) => n + quantity)
    setStatus(`Added to your cart: ${quantity} ${quantity === 1 ? 'pair' : 'pairs'}, US ${size}.`)
  }

  function toggleWishlist() {
    setWishlisted((w) => {
      setStatus(w ? 'Removed from wishlist.' : 'Saved to wishlist.')
      return !w
    })
  }

  function pickStore({ store, size: s }) {
    setPickup({ store, size: s })
    setSize(s)
    setSizeError('')
  }

  return (
    <>
      <a href="#main" className="skip-link">
        Skip to product
      </a>
      <header className="site-header">
        <div className="header-top">
          <a href="/" className="logo">
            Stride
          </a>
          <SearchBox />
          <a href="/cart" className="cart-link">
            Cart <span className="cart-count">{cartCount}</span>
            <span className="visually-hidden"> items</span>
          </a>
        </div>
        <MainMenu />
      </header>

      <main id="main">
        <Breadcrumb
          steps={[
            { label: 'Shop', href: '/shop' },
            { label: 'Trail', href: '/shop/trail' },
          ]}
          current={PRODUCT.name}
        />

        <div className="product">
          <PhotoGallery color={color} productName={PRODUCT.name} />

          <div className="product-info">
            <h1>{PRODUCT.name}</h1>
            <p className="intro">{PRODUCT.intro}</p>
            <PriceInfo price={PRODUCT.price} />

            <ColorPicker color={color} onChange={setColor} />

            <div className="field size-field">
              <span className="field-label">Size</span>
              <div className="size-row">
                <SizePicker
                  size={size}
                  soldOut={SOLD_OUT}
                  buttonRef={sizeButtonRef}
                  onChange={(s) => {
                    setSize(s)
                    setSizeError('')
                  }}
                />
                <button
                  type="button"
                  className="link-button"
                  ref={guideButtonRef}
                  onClick={() => setGuideOpen(true)}
                >
                  Size guide
                </button>
              </div>
              {sizeError && (
                <p className="field-error" role="alert">
                  {sizeError}
                </p>
              )}
            </div>
            {guideOpen && <SizeGuide onClose={() => setGuideOpen(false)} />}

            <section className="store-section" aria-labelledby="store-heading">
              <h2 id="store-heading">Check stores near you</h2>
              <StoreAvailability pickup={pickup} onPick={pickStore} />
            </section>

            <Quantity value={quantity} onChange={setQuantity} />

            <div className="field">
              <span className="field-label">Delivery</span>
              <DeliveryDate selected={delivery} onSelect={setDelivery} />
            </div>

            <div className="purchase">
              <button type="button" className="primary-button" onClick={addToCart}>
                Add to cart
              </button>
              <button
                type="button"
                className="wishlist-button"
                aria-pressed={wishlisted ? 'true' : 'false'}
                onClick={toggleWishlist}
              >
                <span aria-hidden="true">{wishlisted ? '♥' : '♡'}</span> Add to wishlist
              </button>
            </div>
            <div role="status" className="status">
              {status}
            </div>
          </div>
        </div>

        <Faq />
        <ProductTabs />
      </main>

      <Footer />
    </>
  )
}

