cat > src/styles.css <<'EOF'
:root {
  --ink: #1b1f24;
  --muted: #4b5563;
  --line: #d1d5db;
  --surface: #f5f6f8;
  --accent: #0b5cad;
  --accent-ink: #ffffff;
  --danger: #b42318;
  --focus: #1d4ed8;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  color: var(--ink);
  background: #ffffff;
  line-height: 1.5;
}

* { box-sizing: border-box; }
body { margin: 0; }

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0, 0, 0, 0);
  white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute; left: 8px; top: -100px;
  background: var(--ink); color: #fff; padding: 8px 12px; z-index: 10;
}
.skip-link:focus { top: 8px; }

button, input, select { font: inherit; }
button {
  min-height: 32px; min-width: 32px;
  cursor: pointer;
}
button:disabled { cursor: not-allowed; color: #6b7280; }

a { color: var(--accent); }

/* Header */
.site-header { border-bottom: 1px solid var(--line); }
.header-top {
  display: flex; align-items: center; gap: 16px;
  padding: 12px 24px; flex-wrap: wrap;
}
.logo { font-weight: 800; font-size: 1.25rem; color: var(--ink); text-decoration: none; }
.search { flex: 1; min-width: 220px; max-width: 480px; position: relative; }
.search input {
  width: 100%; padding: 8px 12px; border: 1px solid #6b7280; border-radius: 6px;
}
.suggestions {
  position: absolute; top: 100%; left: 0; right: 0; z-index: 5;
  list-style: none; margin: 4px 0 0; padding: 4px 0;
  background: #fff; border: 1px solid var(--line); border-radius: 6px;
  box-shadow: 0 4px 12px rgba(0,0,0,.12);
}
.suggestions li { padding: 8px 12px; cursor: pointer; }
.suggestions li[aria-selected="true"] { background: #e0ecff; }
.cart-link { color: var(--ink); text-decoration: none; font-weight: 600; }
.cart-count {
  display: inline-block; min-width: 24px; padding: 0 6px; text-align: center;
  background: var(--ink); color: #fff; border-radius: 12px;
}

.main-menu { padding: 0 24px; }
.main-menu-list { display: flex; gap: 8px; list-style: none; margin: 0; padding: 0; flex-wrap: wrap; align-items: flex-start; }
.main-menu-list > li { position: relative; }
.main-menu > .main-menu-list > li > button,
.main-menu-list > li > a {
  background: none; border: 0; padding: 10px 12px; font-weight: 600; color: var(--ink); text-decoration: none;
}
.menu-panel {
  position: absolute; top: 100%; left: 0; min-width: 240px; z-index: 6;
  background: #fff; border: 1px solid var(--line); border-radius: 6px; padding: 8px;
  box-shadow: 0 4px 12px rgba(0,0,0,.12);
}
.menu-panel[hidden] { display: none; }
.menu-panel ul { list-style: none; margin: 0; padding: 0; }
.menu-panel li a, .menu-panel li button {
  display: block; width: 100%; text-align: left; padding: 8px; background: none; border: 0; color: var(--accent);
}
.menu-back { font-weight: 600; }
.menu-drill-title { font-weight: 700; margin: 8px; }

/* Breadcrumb */
.breadcrumb { padding: 12px 24px 0; font-size: .9rem; }
.breadcrumb ol { display: flex; flex-wrap: wrap; gap: 6px; list-style: none; margin: 0; padding: 0; }
.breadcrumb li + li::before { content: '/'; margin-right: 6px; color: var(--muted); }
.breadcrumb a { color: var(--accent); }

/* Product layout */
.product {
  display: grid; grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
  gap: 32px; padding: 24px; align-items: start;
}
@media (max-width: 800px) { .product { grid-template-columns: 1fr; } }

.gallery-stage { background: var(--surface); border-radius: 8px; overflow: hidden; }
.gallery-stage img { display: block; width: 100%; height: auto; }
.gallery-controls { display: flex; gap: 8px; align-items: center; margin-top: 12px; }
.gallery-controls button {
  padding: 6px 12px; border: 1px solid var(--line); border-radius: 6px; background: #fff;
}
.gallery-count { margin-left: auto; color: var(--muted); }

.product-info h1 { font-size: 2rem; margin: 0 0 4px; }
.intro { color: var(--muted); margin-top: 0; }
.price-row { display: flex; align-items: center; gap: 8px; margin-bottom: 16px; }
.price { font-size: 1.5rem; font-weight: 700; }
.price-info-wrap { position: relative; }
.info-button {
  width: 24px; height: 24px; min-width: 24px; min-height: 24px; padding: 0; border-radius: 50%;
  border: 1px solid var(--muted); background: #fff; font-weight: 700; font-size: .8rem;
}
.tooltip {
  position: absolute; left: 32px; top: -6px; width: max-content; max-width: 220px; z-index: 4;
  background: var(--ink); color: #fff; padding: 6px 10px; border-radius: 6px; font-size: .9rem;
}

.field { margin: 16px 0; border: 0; padding: 0; }
.field > label, .field-label, .field legend { display: block; font-weight: 600; margin-bottom: 6px; }
.field legend { padding: 0; }
.select-button, .primary-button, .wishlist-button {
  min-height: 44px; padding: 10px 16px; border-radius: 6px; border: 1px solid #6b7280; background: #fff; color: var(--ink);
}
.select-button { min-width: 200px; text-align: left; }
.primary-button { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); font-weight: 700; }
.link-button { background: none; border: 0; color: var(--accent); text-decoration: underline; padding: 6px; }

/* Color */
.color-field fieldset { border: 0; padding: 0; }
.swatch-row { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.swatch-option { display: inline-flex; align-items: center; gap: 6px; cursor: pointer; }
.swatch {
  -webkit-appearance: none; appearance: none;
  width: 32px; height: 32px; min-width: 32px; min-height: 32px;
  border-radius: 50%; border: 2px solid #fff; box-shadow: 0 0 0 1px #6b7280; margin: 0;
  cursor: pointer;
}
.swatch:checked { box-shadow: 0 0 0 3px #fff, 0 0 0 5px var(--ink); }
.swatch:focus-visible { outline: 3px solid var(--focus); outline-offset: 3px; }

/* Size */
.size-row { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.size-picker { position: relative; }
.size-list {
  position: absolute; top: 100%; left: 0; min-width: 200px; z-index: 5;
  list-style: none; margin: 4px 0 0; padding: 4px 0;
  background: #fff; border: 1px solid var(--line); border-radius: 6px;
  box-shadow: 0 4px 12px rgba(0,0,0,.12);
}
.size-list:focus-visible { outline: 3px solid var(--focus); }
.size-list li { padding: 8px 12px; cursor: pointer; }
.size-list li.is-active { background: #e0ecff; }
.size-list li[aria-selected="true"] { font-weight: 700; }
.size-list li[aria-disabled="true"] { color: #6b7280; text-decoration: line-through; cursor: not-allowed; }
.field-error { color: var(--danger); font-weight: 600; margin: 6px 0 0; }

/* Store grid */
.store-section h2 { font-size: 1.1rem; margin: 24px 0 8px; }
.store-grid { border-collapse: collapse; width: 100%; font-size: .9rem; }
.store-grid th, .store-grid td { border: 1px solid var(--line); padding: 6px; text-align: center; }
.store-grid th[scope="row"] { text-align: left; font-weight: 600; }
.store-grid .cell { width: 100%; min-height: 36px; border: 1px solid transparent; border-radius: 4px; background: #e8f5e9; }
.store-grid .cell:disabled { background: #f3f4f6; text-decoration: line-through; }
.store-grid .cell.is-selected { background: var(--accent); color: #fff; }
.pickup-note { font-weight: 600; }

/* Quantity */
.quantity { display: inline-flex; align-items: stretch; }
.quantity button { width: 44px; border: 1px solid #6b7280; background: #fff; font-size: 1.2rem; }
.quantity input {
  width: 64px; text-align: center; border: 1px solid #6b7280; border-left: 0; border-right: 0;
}

/* Delivery calendar */
.delivery-chosen { font-weight: 600; margin: 8px 0 0; }
.calendar-panel {
  margin-top: 8px; padding: 12px; border: 1px solid var(--line); border-radius: 8px; background: #fff; max-width: 340px;
}
.calendar-nav { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; font-weight: 600; }
.calendar { border-collapse: collapse; width: 100%; text-align: center; }
.calendar th { font-size: .8rem; color: var(--muted); padding: 4px; }
.calendar td { padding: 2px; }
.calendar td button {
  width: 40px; height: 40px; min-width: 40px; min-height: 40px; border: 1px solid transparent; border-radius: 6px; background: #fff;
}
.calendar td button:disabled { color: #9ca3af; text-decoration: line-through; }
.calendar td button:not(:disabled):hover { border-color: #6b7280; }

/* Purchase */
.purchase { display: flex; gap: 12px; align-items: center; flex-wrap: wrap; margin: 24px 0 8px; }
.purchase .primary-button { min-width: 200px; }
.wishlist-button { background: #fff; }
.status { min-height: 1.5em; margin-top: 8px; font-weight: 600; color: #065f46; }

/* Dialog */
.dialog-backdrop {
  position: fixed; inset: 0; background: rgba(0,0,0,.5); display: flex; align-items: center;
  justify-content: center; padding: 16px; z-index: 20;
}
.dialog {
  background: #fff; border-radius: 10px; padding: 20px; max-width: 560px; width: 100%; max-height: 90vh; overflow: auto;
}
.dialog-header { display: flex; justify-content: space-between; align-items: center; }
.dialog-header h2 { margin: 0; font-size: 1.3rem; }
.size-chart { border-collapse: collapse; width: 100%; margin: 12px 0; }
.size-chart th, .size-chart td { border: 1px solid var(--line); padding: 6px; text-align: left; }
.size-calc h3 { margin: 12px 0 8px; font-size: 1.05rem; }
.size-calc input[type="number"] { padding: 8px; border: 1px solid #6b7280; border-radius: 6px; width: 160px; }
.inline-option { margin-right: 16px; }
.size-result { font-weight: 700; font-size: 1.1rem; }

/* More information tabs */
.more-info { padding: 24px; }
.more-info h2, .faq h2 { font-size: 1.4rem; }
.tablist { display: flex; gap: 4px; border-bottom: 2px solid var(--line); flex-wrap: nowrap; overflow-x: auto; }
.tab {
  background: none; border: 0; padding: 12px 16px; border-bottom: 3px solid transparent; margin-bottom: -2px; color: var(--muted); font-weight: 600;
}
.tab.is-selected { color: var(--ink); border-bottom-color: var(--accent); }
.tabpanel { padding: 16px 0; }
.tabpanel:focus-visible { outline: 3px solid var(--focus); }
.reviews { list-style: none; padding: 0; }
.reviews li { margin-bottom: 12px; }

/* FAQ */
.faq { padding: 24px; border-top: 1px solid var(--line); }
.faq-item { border-bottom: 1px solid var(--line); }
.faq-item h3 { margin: 0; font-size: 1rem; }
.faq-item button {
  width: 100%; text-align: left; background: none; border: 0; padding: 14px 4px; font-weight: 600;
}
.faq-answer { padding: 0 4px 14px; }
.faq-answer[hidden] { display: none; }

/* Footer */
.site-footer { background: var(--surface); padding: 32px 24px; border-top: 1px solid var(--line); }
.footer-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 24px; }
.footer-group h2 { font-size: 1rem; margin: 0 0 8px; }
.footer-group ul { list-style: none; margin: 0; padding: 0; }
.footer-group li { margin-bottom: 6px; }
.legal { color: var(--muted); font-size: .85rem; margin-top: 24px; }
EOF
